1	// Conversation transcript with stable scroll anchoring: the list follows new
2	// content only while the reader is at the bottom; scrolling up to reread
3	// pins the viewport until they return to the bottom. Tool activity cards
4	// render beneath the assistant message that proposed them, a plan's calls as
5	// one card beneath the message that proposed its first call; the change log and
6	// the manufacturing history render after the conversation item they follow,
7	// in the order they happened.
8	
9	import { Fragment, useLayoutEffect, useRef, useState } from 'react';
10	import { AttachmentInfo, BuildInfo, ChangeInfo, ExportedCopyInfo, PhysicalPrintInfo, ToolActivityInfo } from '../bridge/protocol';
11	import { Message } from '../state/store';
12	import { AttachmentChip } from './AttachmentChip';
13	import { ChangeRows } from './ChangeRows';
14	import { MarkdownMessage } from './MarkdownMessage';
15	import { ToolActivityCard } from './ToolActivityCard';
16	import { PlanActivityCard, planHeadline, planKey, planMembers } from './PlanActivityCard';
17	import { ManufacturingHistoryCard, ManufacturingHistoryEntry } from './ManufacturingHistoryCard';
18	
19	interface Props {
20	  messages: Message[];
21	  attachments: AttachmentInfo[];
22	  streamingMessageId: string | null;
23	  toolActivities: ToolActivityInfo[];
24	  builds: BuildInfo[];
25	  exportedCopies: ExportedCopyInfo[];
26	  physicalPrints: PhysicalPrintInfo[];
27	  changes: ChangeInfo[]; // already filtered to this conversation
28	  onRetry: (messageId: string) => void;
29	  onToolDecision: (actionId: string, decision: 'approve' | 'reject') => void;
30	  onToolCancel: (actionId: string) => void;
31	  // The setup card's expansion is a layer over this thread; the thread dims
32	  // rather than being covered, so the conversation stays legibly there.
33	  dimmed?: boolean;
34	}
35	
36	// What follows one conversation item: history cards and runs of changes, in
37	// seq order. Consecutive changes form one block, which draws as one group.
38	type TimelineBlock =
39	  | { kind: 'history'; seq: number; entry: ManufacturingHistoryEntry }
40	  | { kind: 'changes'; seq: number; changes: ChangeInfo[] };
41	
42	function timeline(history: ManufacturingHistoryEntry[], changes: ChangeInfo[]): TimelineBlock[] {
43	  const items = [
44	    ...history.map((entry) => ({ seq: entry.seq, history: entry, change: undefined })),
45	    ...changes.map((change) => ({ seq: change.seq, history: undefined, change })),
46	  ].sort((a, b) => a.seq - b.seq);
47	  const blocks: TimelineBlock[] = [];
48	  for (const item of items) {
49	    const previous = blocks[blocks.length - 1];
50	    if (item.change && previous?.kind === 'changes') previous.changes.push(item.change);
51	    else if (item.change) blocks.push({ kind: 'changes', seq: item.seq, changes: [item.change] });
52	    else blocks.push({ kind: 'history', seq: item.seq, entry: item.history! });
53	  }
54	  return blocks;
55	}
56	
57	function TimelineBlocks({ blocks }: { blocks: TimelineBlock[] }) {
58	  return (
59	    <>
60	      {blocks.map((block) =>
61	        block.kind === 'history' ? (
62	          <ManufacturingHistoryCard key={`${block.entry.kind}-${block.entry.record.id}`} entry={block.entry} />
63	        ) : (
64	          <ChangeRows key={`changes-${block.seq}`} changes={block.changes} />
65	        ),
66	      )}
67	    </>
68	  );
69	}
70	
71	const inFlight = new Set(['pending', 'approved', 'running']);
72	
73	export function MessageList({
74	  messages,
75	  attachments,
76	  streamingMessageId,
77	  toolActivities,
78	  builds,
79	  exportedCopies,
80	  physicalPrints,
81	  changes,
82	  onRetry,
83	  onToolDecision,
84	  onToolCancel,
85	  dimmed,
86	}: Props) {
87	  const attachmentsById = new Map(attachments.map((attachment) => [attachment.id, attachment]));
88	  const listRef = useRef<HTMLDivElement>(null);
89	  const [followBottom, setFollowBottom] = useState(true);
90	
91	  const handleScroll = () => {
92	    const list = listRef.current;
93	    if (!list) return;
94	    const distanceFromBottom = list.scrollHeight - list.scrollTop - list.clientHeight;
95	    setFollowBottom(distanceFromBottom < 24);
96	  };
97	
98	  useLayoutEffect(() => {
99	    const list = listRef.current;
100	    if (list && followBottom) list.scrollTop = list.scrollHeight;
101	  }, [messages, toolActivities, builds, exportedCopies, physicalPrints, changes, followBottom]);
102	
103	  const history: ManufacturingHistoryEntry[] = [
104	    ...builds.map((record) => ({ kind: 'build' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
105	    ...exportedCopies.map((record) => ({ kind: 'copy' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
106	    ...physicalPrints.map((record) => ({ kind: 'print' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
107	  ];
108	  const activitiesOf = (messageId: string) => toolActivities.filter((activity) => activity.correlationId === messageId);
109	  const plans = planMembers(toolActivities);
110	  const headline = planHeadline(toolActivities);
111	  // A change follows a message or one of its tool activities; both place it
112	  // after that message's group.
113	  const messageOfItem = new Map<string, string>();
114	  for (const message of messages) {
115	    messageOfItem.set(message.id, message.id);
116	    for (const activity of activitiesOf(message.id)) messageOfItem.set(activity.actionId, message.id);
117	  }
118	  const changesAfter = (messageId: string) => changes.filter((change) => messageOfItem.get(change.afterId) === messageId);
119	  const leadingChanges = changes.filter((change) => !messageOfItem.has(change.afterId));
120	  const historyAfter = (messageId: string) => history.filter((entry) => entry.afterMessageId === messageId);
