132	    !activitiesOf(message.id).some((activity) => inFlight.has(activity.state)) &&
133	    !changesAfter(message.id).some((change) => change.actor === 'agent');
134	
135	  return (
136	    <div className={dimmed ? 'message-list thread-dimmed' : 'message-list'} role="log" aria-label="Agent conversation"
137	      ref={listRef} onScroll={handleScroll}>
138	      <TimelineBlocks blocks={timeline(leadingHistory, leadingChanges)} />
139	      {messages.length === 0 && (
140	        <div className="notice">
141	          <h2>Ask the Agent about your print</h2>
142	          <p>
143	            The Agent can describe the open project, the plates and objects on them, the current selection, and the
144	            printer setup — or duplicate the selected object with your approval.
145	          </p>
