246:        if (before != m_known_slice_state.end() && before->second.sliced && !now.sliced)
251:    m_known_slice_state = std::move(state);
    static CommandResult failure(WorkspaceError error, std::string message)
    {
        return {error, std::move(message), std::nullopt};
    }
};

enum class WorkspaceChangeReasons : std::uint32_t {
    None      = 0,
    Selection = 1u << 0,
    Contents  = 1u << 1,
    History   = 1u << 2,
    Transform = 1u << 3,
    Plates    = 1u << 4,
    Project   = 1u << 5,
    Settings  = 1u << 6
};

